actions.action:
// No nexus - no filing required
result.wa_bo_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

// Calculate WA-sourced gross receipts using apportionment
// B&O tax is on gross receipts, not net income
result.wa_gross_receipts =
  revenue.total_revenue * apportionment.apportionment_percentage;

            // Qualifies for small business B&O credit
            result.wa_qualifies_for_small_business_credit = true;

            // Calculate credit amount (simplified - actual calculation is more complex)
            // Credit phases out as revenue approaches $250K
            double credit_percentage = 1.0 - (revenue.total_revenue / result.wa_small_business_credit_threshold);

            // Maximum credit is approximately $100-120 per month ($1,200-1,440 annually)
            double max_annual_credit = 1440.0;
            result.wa_small_business_credit = max_annual_credit * credit_percentage;

            // Calculate B&O tax on gross receipts
            result.wa_bo_tax = result.wa_gross_receipts * result.wa_bo_tax_rate;

            // Apply small business credit (calculated by table 51060)
            result.wa_bo_tax = Math.max(0.0, result.wa_bo_tax - result.wa_small_business_credit);

            // Apply high tech credit if applicable
            result.wa_bo_tax = Math.max(0.0, result.wa_bo_tax - result.wa_high_tech_credit);

            // Apply aerospace credit if applicable
            result.wa_bo_tax = Math.max(0.0, result.wa_bo_tax - result.wa_aerospace_credit);

            // Apply other state credits
            result.wa_bo_tax = Math.max(0.0, result.wa_bo_tax - apportionment.state_credits);

            // Washington B&O tax is reported as "state tax" for consistency with framework
            // Note: This is NOT an income tax
            apportionment.state_tax = result.wa_bo_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
